TASK AND SPECIFICATIONS
{
  "schema_version": 1,
  "id": "SELF001",
  "kind": "self_built",
  "title": "Guarded motor with retained run command",
  "difficulty": "easy",
  "provenance": {
    "source_type": "independent_synthesis",
    "source_file": "scripts/build_self_dataset.py",
    "source_index": 1,
    "adaptation": "Independently specified for this project; no public task was copied. The coding assistant chose the state variables, priority order and fixed scan traces, then reviewed the traces against a separate Python transition implementation.",
    "rationale": "A packaging motor uses a door guard as a scan-level permissive and a retained operator run request.",
    "review": "Assistant consistency review of initialization, simultaneous commands, retained state and recovery boundaries; independent Python oracle checked against manual expected traces. Not an industrial safety certification or external expert review."
  },
  "requirements": "Implement a guarded motor latch. Inputs are Start, Stop and GuardClosed. Run initially is FALSE. On every scan, Stop or an open guard forces Run FALSE. Otherwise Start sets Run TRUE; without Start retain Run. If Start remains held while the guard closes, starting on that closing scan is permitted. This is logic for a teaching controller, not a replacement for a safety-rated guard circuit.",
  "scenario": "A packaging motor uses a door guard as a scan-level permissive and a retained operator run request.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "Start",
      "type": "BOOL",
      "description": "Operator start request"
    },
    {
      "direction": "INPUT",
      "name": "Stop",
      "type": "BOOL",
      "description": "Stop request"
    },
    {
      "direction": "INPUT",
      "name": "GuardClosed",
      "type": "BOOL",
      "description": "Door permissive"
    },
    {
      "direction": "OUTPUT",
      "name": "Run",
      "type": "BOOL",
      "description": "Motor run command"
    }
  ],
  "initial_conditions": {
    "Run": false
  },
  "scan_semantics": "At scan k, sample every input once, read retained pre-state q[k], execute one transition, and observe outputs O[k] at the end of that same scan. Updated state becomes q[k+1]. Reset the instance before each test. Step 0 executes normally; initial conditions describe pre-state, not an extra delayed scan. All timing in this task is explicitly counted in invocations, not wall time.",
  "safety_priority": [
    "Open guard and Stop override Start",
    "Loss of permissive clears the retained latch"
  ],
  "assumptions": [
    "Inputs are level-sensitive; no start edge is required."
  ],
  "atomic_propositions": {
    "Start": "Operator start request Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Stop": "Stop request Boolean names are propositions; numeric names appear only inside defined predicates.",
    "GuardClosed": "Door permissive Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Run": "Motor run command Boolean names are propositions; numeric names appear only inside defined predicates.",
    "first": "True only on the first invocation after resetting the FB instance.",
    "qRun": "Run retained from the preceding invocation, initially FALSE."
  },
  "ltl": [
    {
      "id": "P1",
      "formula": "G(first -> !qRun)",
      "explanation": "The instance starts with no retained run request."
    },
    {
      "id": "P2",
      "formula": "G((Stop | !GuardClosed) -> !Run)",
      "explanation": "Stop and guard override every startup request in the same scan."
    },
    {
      "id": "P3",
      "formula": "G((Start & !Stop & GuardClosed) -> Run)",
      "explanation": "A permitted start takes effect at end of the sampled scan."
    },
    {
      "id": "P4",
      "formula": "G((!Start & !Stop & GuardClosed) -> (Run <-> qRun))",
      "explanation": "Retain the preceding run value without a new command."
    },
    {
      "id": "P5",
      "formula": "G(Run -> X(Stop | !GuardClosed | Run))",
      "explanation": "Across invocations, run persists unless a higher-priority input intervenes."
    }
  ],
  "tests": [
    {
      "id": "latch",
      "purpose": "Initialize, start, hold and stop",
      "steps": [
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "GuardClosed": true
          },
          "expected": {
            "Run": false
          }
        },
        {
          "inputs": {
            "Start": true,
            "Stop": false,
            "GuardClosed": true
          },
          "expected": {
            "Run": true
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "GuardClosed": true
          },
          "expected": {
            "Run": true
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": true,
            "GuardClosed": true
          },
          "expected": {
            "Run": false
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "GuardClosed": true
          },
          "expected": {
            "Run": false
          }
        }
      ]
    },
    {
      "id": "priority",
      "purpose": "Simultaneous requests and guard recovery",
      "steps": [
        {
          "inputs": {
            "Start": true,
            "Stop": true,
            "GuardClosed": true
          },
          "expected": {
            "Run": false
          }
        },
        {
          "inputs": {
            "Start": true,
            "Stop": false,
            "GuardClosed": false
          },
          "expected": {
            "Run": false
          }
        },
        {
          "inputs": {
            "Start": true,
            "Stop": false,
            "GuardClosed": true
          },
          "expected": {
            "Run": true
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "GuardClosed": false
          },
          "expected": {
            "Run": false
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "GuardClosed": true
          },
          "expected": {
            "Run": false
          }
        }
      ]
    }
  ]
}
